spec.expr:
histogram_quantile(
  0.95,
  sum by (le, service_namespace, service_name) (
    rate(
      http_server_request_duration_seconds_bucket{
        service_namespace=~"$service_namespace",
        service_name=~"$service_name"
      }[$__rate_interval]
    )
  )
)

avg by (service_namespace, service_name) (
  rate(
    http_server_request_duration_seconds_sum{
        service_namespace=~"$service_namespace",
        service_name=~"$service_name"
    }[$__rate_interval]
  )
)
/
avg by (service_namespace, service_name) (
  rate(
    http_server_request_duration_seconds_count{
        service_namespace=~"$service_namespace",
        service_name=~"$service_name"
    }[$__rate_interval]
  )
)

histogram_quantile(
  0.95,
  sum by (le, service_namespace, service_name) (
    rate(
      rpc_server_duration_milliseconds_bucket{
        service_namespace=~"$service_namespace",
        service_name=~"$service_name"
      }[$__rate_interval]
    ) / 1000
  )
)

avg by (service_namespace, service_name) (
  rate(
    rpc_server_duration_milliseconds_sum{
        service_namespace=~"$service_namespace",
        service_name=~"$service_name"
    }[$__rate_interval]
  ) / 1000
)
/
avg by (service_namespace, service_name) (
  rate(
    rpc_server_duration_milliseconds_count{
        service_namespace=~"$service_namespace",
        service_name=~"$service_name"
    }[$__rate_interval]
  )
)

(
        sum by (outbound.service) (
            label_join(
                rate(http_client_request_duration_seconds_count{
                    service_namespace=~"$service_namespace",
                    service_name=~"$service_name",
                    http.response.status_code=~"5.."
                }[$__rate_interval]),
                "outbound.service",
                " ",
                "server_address",
                "http_request_method"
            )
        )
     / 
        sum by (outbound.service) (
            label_join(
                rate(http_client_request_duration_seconds_count{
                    service_namespace=~"$service_namespace",
                    service_name=~"$service_name"
                }[$__rate_interval]),
                "outbound.service",
                " ",
                "server_address",
                "http_request_method"
            )
        )
    ) or (0 * 
        sum by (outbound.service) (
            label_join(
                rate(http_client_request_duration_seconds_count{
                    service_namespace=~"$service_namespace",
                    service_name=~"$service_name"
                }[$__rate_interval]),
                "outbound.service",
                " ",
                "server_address",
                "http_request_method"
            )
        )
    )

histogram_quantile(
    0.99,
    sum by (le, outbound.service) (
        label_join(
        rate(http_client_request_duration_seconds_bucket{
                service_namespace=~"$service_namespace",
                service_name=~"$service_name"
            }[5m]),
                "outbound.service",
                " ",
                "server_address",
                "http_request_method"
        )
    )
)
